import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { EmailService } from '../../core/services/email.service';
import { ThemeService } from '../../core/services/theme.service';

interface NavItem {
  id: string;
  label: string;
  icon: string;
  folder: 'inbox' | 'sent' | 'drafts' | 'trash';
  count?: number;
}

@Component({
  selector: 'app-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.scss']
})
export class SidebarComponent implements OnInit {
  @Output() folderChange = new EventEmitter<string>();

  activeFolder = 'inbox';
  isDark = false;

  navItems: NavItem[] = [
    { id: 'inbox', label: 'Inbox', icon: 'inbox', folder: 'inbox' },
    { id: 'sent', label: 'Sent', icon: 'send', folder: 'sent' },
    { id: 'drafts', label: 'Drafts', icon: 'draft', folder: 'drafts' },
    { id: 'trash', label: 'Trash', icon: 'trash', folder: 'trash' }
  ];

  constructor(
    private emailService: EmailService,
    private themeService: ThemeService
  ) {}

  ngOnInit(): void {
    this.emailService.getFolderCounts().subscribe(counts => {
      this.navItems = this.navItems.map(item => ({
        ...item,
        count: counts[item.id] || undefined
      }));
    });

    this.themeService.isDark$.subscribe(isDark => this.isDark = isDark);
  }

  selectFolder(folder: string): void {
    this.activeFolder = folder;
    this.folderChange.emit(folder);
  }

  toggleTheme(): void {
    this.themeService.toggle();
  }
}
<aside class="sidebar">
  <!-- Logo -->
  <div class="sidebar__logo">
    <div class="sidebar__logo-mark">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
        <rect width="20" height="20" rx="6" fill="#e8673c"/>
        <path d="M3 7l7 5 7-5" stroke="white" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        <rect x="3" y="6" width="14" height="10" rx="2" stroke="white" stroke-width="1.5"/>
      </svg>
    </div>
    <span class="sidebar__logo-name">Mailbox</span>
  </div>

  <!-- Compose Button -->
  <button class="sidebar__compose">
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
      <path d="M8 3v10M3 8h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
    </svg>
    Compose
  </button>

  <!-- Navigation -->
  <nav class="sidebar__nav">
    <p class="sidebar__nav-label">Folders</p>
    <ul>
      <li *ngFor="let item of navItems">
        <button
          class="sidebar__nav-item"
          [class.sidebar__nav-item--active]="activeFolder === item.id"
          (click)="selectFolder(item.id)">
          <span class="sidebar__nav-icon">
            <!-- Inbox -->
            <svg *ngIf="item.icon === 'inbox'" width="18" height="18" viewBox="0 0 18 18" fill="none">
              <path d="M2 11h3.5l1.5 2h4l1.5-2H16V5a1 1 0 00-1-1H3a1 1 0 00-1 1v6z"
                stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/>
            </svg>
            <!-- Send -->
            <svg *ngIf="item.icon === 'send'" width="18" height="18" viewBox="0 0 18 18" fill="none">
              <path d="M2 2l14 7-14 7V11l10-2-10-2V2z"
                stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/>
            </svg>
            <!-- Draft 
            <svg *ngIf="item.icon === 'draft'" width="18" height="18" viewBox="0 0 18 18" fill="none">
              <rect x="3" y="2" width="12" height="14" rx="2" stroke="currentColor" stroke-width="1.4"/>
              <path d="M6 6h6M6 9h6M6 12h4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/>
            </svg>-->
            <img src="assets/avatars/drafts.png" width="18" height="18" viewBox="0 0 18 18" fill="none"
            stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/>

            <!-- Trash 
            <svg *ngIf="item.icon === 'trash'" width="18" height="18" viewBox="0 0 18 18" fill="none">
              <path d="M3 5h12M7 5V3h4v2M5 5l1 10h6l1-10"
                stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>-->
            <img src="assets/avatars/del.png" width="18" height="18" viewBox="0 0 18 18" fill="none"/>
          </span>
          <span class="sidebar__nav-label-text">{{ item.label }}</span>
          <span class="sidebar__nav-badge" *ngIf="item.count && item.count > 0">{{ item.count }}</span>
        </button>
      </li>
    </ul>
  </nav>

  <!-- Bottom Controls -->
  <div class="sidebar__bottom">
    <button class="sidebar__theme-toggle" (click)="toggleTheme()" [title]="isDark ? 'Light mode' : 'Dark mode'">
      <!-- Sun -->
      <svg *ngIf="isDark" width="16" height="16" viewBox="0 0 16 16" fill="none">
        <circle cx="8" cy="8" r="3" stroke="currentColor" stroke-width="1.4"/>
        <path d="M8 1v2M8 13v2M1 8h2M13 8h2M3.1 3.1l1.4 1.4M11.5 11.5l1.4 1.4M11.5 3.1l-1.4 1.4M4.5 11.5l-1.4 1.4"
          stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/>
      </svg>
      <!-- Moon -->
      <svg *ngIf="!isDark" width="16" height="16" viewBox="0 0 16 16" fill="none">
        <path d="M14 10A6 6 0 016 2a6 6 0 100 12 6 6 0 008-4z"
          stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/>
      </svg>
      {{ isDark ? 'Light mode' : 'Dark mode' }}
    </button>

    <div class="sidebar__user">
      <div class="sidebar__user-avatar">Y</div>
      <div class="sidebar__user-info">
        <p class="sidebar__user-name">You</p>
        <p class="sidebar__user-email">me@mymail.com</p>
      </div>
    </div>
  </div>
</aside>
